const pipelineWorkDue = `-- name: PipelineWorkDue :many

SELECT run_id,attempts FROM pipeline_work WHERE next_attempt_at<=$1::pg_catalog.timestamptz ORDER BY next_attempt_at,run_id LIMIT $2
`

type PipelineWorkDueParams struct {
	Now time.Time
	Lim int32
}

type PipelineWorkDueRow struct {
	RunID    string
	Attempts int32
}

// Pipeline runs on the work kit (pipeline_work.go, docs/designs/fleet-standard.md S6): one pipeline_work row per run
// the kit still has to move; the retry columns are the kit's (work_kit.go).
func (q *Queries) PipelineWorkDue(ctx context.Context, arg PipelineWorkDueParams) ([]PipelineWorkDueRow, error) {
	rows, err := q.db.Query(ctx, pipelineWorkDue, arg.Now, arg.Lim)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []PipelineWorkDueRow
	for rows.Next() {
		var i PipelineWorkDueRow
		if err := rows.Scan(&i.RunID, &i.Attempts); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const pipelineWorkEnsure = `-- name: PipelineWorkEnsure :execrows
INSERT INTO pipeline_work(run_id) VALUES($1) ON CONFLICT DO NOTHING
`

// A running run has its row; nothing when it has one.
func (q *Queries) PipelineWorkEnsure(ctx context.Context, runID string) (int64, error) {
	result, err := q.db.Exec(ctx, pipelineWorkEnsure, runID)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}
